from rest_framework.views import exception_handler
from rest_framework.exceptions import AuthenticationFailed, ValidationError, NotFound
from rest_framework.response import Response
from rest_framework import status

def custom_exception_handler(exc, context):
    # Call the default exception handler first
    response = exception_handler(exc, context)

    # If no response is generated by the default handler
    if response is None:
        if isinstance(exc, ValidationError):
            status_code = status.HTTP_400_BAD_REQUEST
            error_detail = exc.detail
        elif isinstance(exc, NotFound):
            status_code = status.HTTP_404_NOT_FOUND
            error_detail = exc.detail
        elif isinstance(exc, AuthenticationFailed):
            status_code = status.HTTP_401_UNAUTHORIZED
            error_detail = (
                exc.detail.get('error')
                if isinstance(exc.detail, dict) and 'error' in exc.detail
                else exc.detail
            )
        else:
            status_code = status.HTTP_500_INTERNAL_SERVER_ERROR
            error_detail = str(exc) if not isinstance(exc, Exception) else "An unexpected error occurred"

        return Response({
            "status": status_code,
            "success": False,
            "error": error_detail
        }, status=status_code)

    # Customize AuthenticationFailed response if already handled by DRF
    if isinstance(exc, AuthenticationFailed):
        response.data = {
            "status": status.HTTP_401_UNAUTHORIZED,
            "success": False,
            "error": (
                exc.detail.get('error')
                if isinstance(exc.detail, dict) and 'error' in exc.detail
                else str(exc.detail)
            )
        }

    return response
